const formatBeijingDateTime=(iso?:string)=>{if(!iso)return '等待同步'; const date=new Date(iso); if(Number.isNaN(date.getTime()))return '时间未知'; return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(date).replace(/\//g,'-')};
