const demoCandles=(symbol:string, interval:string):CandlePayload=>{
 const asset=(Object.keys(symbolMap) as Asset[]).find(name=>symbolMap[name]===symbol)||'黄金';
 const base=quoteNumber(assets[asset].price);
 const step=interval==='monthly'?30*86400000:interval==='weekly'?7*86400000:86400000;
 const rows:Candle[]=[];
 let previous=base*0.972;
 for(let i=0;i<36;i+=1){
  const drift=0.004*Math.sin(i*.63)+(i/35)*.012;
  const close=base*(.972+drift);
  const open=previous;
  const high=Math.max(open,close)*(1+.0025+.001*Math.abs(Math.sin(i)));
  const low=Math.min(open,close)*(1-.0025-.001*Math.abs(Math.cos(i)));
  rows.push({time:new Date(Date.now()-(35-i)*step).toISOString(),open,high,low,close});
  previous=close;
 }
 return {symbol,name:asset,interval,provider:'demo',data_mode:'demo_fallback',currency:assetCurrency(asset),data_label:'本地演示K线',is_live:false,synthetic:true,as_of:new Date().toISOString(),source_url:'https://www.alphavantage.co/documentation/',freshness:'演示数据',note:'免费源未返回可用历史K线，已显示本地演示形态；不代表交易所实时 OHLC。',candles:rows};
};

