 const [refresh,setRefresh]=useState(60); const [refreshTick,setRefreshTick]=useState(0); const [updated,setUpdated]=useState('刚刚'); const [beijingTime,setBeijingTime]=useState(''); const [toast,setToast]=useState(''); const [mobileNav,setMobileNav]=useState(false); const [filter,setFilter]=useState<'全部'|'已验证'|'变化'>('全部'); const [selected,setSelected]=useState<Event|null>(null); const [showQuality,setShowQuality]=useState(false); const [optimizationFilter,setOptimizationFilter]=useState<OptimizationFilter>('全部'); const [compact,setCompact]=useState(false); const [alerts,setAlerts]=useState(true); const [showCalendar,setShowCalendar]=useState(false); const [snapshot,setSnapshot]=useState<Snapshot|null>(null); const [globalQuotes,setGlobalQuotes]=useState<Snapshot[]>([]); const [domesticQuotes,setDomesticQuotes]=useState<Snapshot[]>([]); const [domesticSync,setDomesticSync]=useState<BoardSync|null>(null); const [domesticError,setDomesticError]=useState(''); const [dataStatus,setDataStatus]=useState('静态演示'); const [eventWindow,setEventWindow]=useState<'全部'|'过去7天'|'未来7天'>('全部'); const [dynamicEvents,setDynamicEvents]=useState<Event[]>([]); const [dynamicTimeline,setDynamicTimeline]=useState<WeekEvent[]>([]); const [eventSyncStatus,setEventSyncStatus]=useState('等待同步'); const [eventSyncedAt,setEventSyncedAt]=useState(''); const [eventSyncLatency,setEventSyncLatency]=useState<number|null>(null); const [eventSyncError,setEventSyncError]=useState(''); const [uploads,setUploads]=useState<ImageMeta[]>([]); const [imageAnalysis,setImageAnalysis]=useState<ImageAnalysis[]>([]); const [imageBusy,setImageBusy]=useState(false); const [imageError,setImageError]=useState(''); const [imageUrlInput,setImageUrlInput]=useState(''); const [imageUrlError,setImageUrlError]=useState(''); const [searchOpen,setSearchOpen]=useState(false); const [syncStatus,setSyncStatus]=useState('等待同步'); const [lastSyncedAt,setLastSyncedAt]=useState(''); const [syncLatency,setSyncLatency]=useState<number|null>(null); const [syncError,setSyncError]=useState(''); const [candleInterval,setCandleInterval]=useState<'daily'|'weekly'|'monthly'>('daily'); const [candles,setCandles]=useState<CandlePayload|null>(null); const [candleStatus,setCandleStatus]=useState<CandleStatus>('idle'); const [candleError,setCandleError]=useState(''); const [privateAuth,setPrivateAuth]=useState<PrivateAuthState>('unknown'); const [privateCode,setPrivateCode]=useState(''); const [privateMessage,setPrivateMessage]=useState(''); const [privateSessionExpiresAt,setPrivateSessionExpiresAt]=useState(''); const [ctpPayload,setCtpPayload]=useState<CtpPayload|null>(null); const [ctpStatus,setCtpStatus]=useState<'idle'|'loading'|'ready'|'error'>('idle'); const [privateRefreshTick,setPrivateRefreshTick]=useState(0);
 const uploadIdRef=useRef(0);
