 const assetOptions=useMemo(()=>{const q=query.trim().toLowerCase(); const options=(Object.keys(assets) as Asset[]); return q?options.filter(x=>x.toLowerCase().includes(q)||assets[x].symbol.toLowerCase().includes(q)):options},[query]);
