 useEffect(()=>{let cancelled=false; const controller=new AbortController(); const apiBase=process.env.NEXT_PUBLIC_API_URL||''; const started=performance.now(); setEventSyncStatus('同步中'); setEventSyncError(''); fetch(`${apiBase}/api/v1/events`,{cache:'no-store',signal:controller.signal}).then(response=>{if(!response.ok)throw new Error('events');return response.json() as Promise<EventsPayload>}).then(payload=>{if(cancelled)return; const items=Array.isArray(payload.items)?payload.items.filter(item=>item&&typeof item.title==='string'&&typeof item.sourceUrl==='string'):[]; const timeline=Array.isArray(payload.timeline)?payload.timeline:[]; setDynamicEvents(items);setDynamicTimeline(timeline);setEventSyncedAt(payload.sync?.synced_at||payload.fetched_at||new Date().toISOString());setEventSyncLatency(typeof payload.sync?.latency_ms==='number'?payload.sync.latency_ms:Math.round(performance.now()-started));setEventSyncStatus(payload.status==='provider_error'?'本地回退':items.length?'已同步':'空结果');if(payload.status==='provider_error'||payload.error)setEventSyncError('全球事件源暂时不可用，已保留本地计划窗口')}).catch(error=>{if(cancelled||error?.name==='AbortError')return;setDynamicEvents([]);setDynamicTimeline([]);setEventSyncLatency(Math.round(performance.now()-started));setEventSyncStatus('本地回退');setEventSyncError('全球事件接口未连接，已保留本地计划窗口')}); return()=>{cancelled=true;controller.abort()}},[refreshTick]);
 const currentEvents=useMemo(()=>{const live=dynamicEvents.filter(e=>e.asset===asset); return live.length?live:(events.some(e=>e.asset===asset)?events:fallbackEvents(asset))},[asset,dynamicEvents]);
