 const timelineSource=useMemo(()=>{const merged=[...dynamicTimeline,...weekEvents]; const seen=new Set<string>(); const matching=merged.filter(e=>{if(!e.assets.includes(asset))return false; const key=`${e.sourceUrl}|${e.title}`; if(seen.has(key))return false; seen.add(key); return true}); return matching.length?matching:fallbackWeekEvents(asset)},[asset,dynamicTimeline]);
