 const updateUpload=(id:string,patch:Partial<ImageMeta>)=>setUploads(prev=>prev.map(item=>item.id===id?{...item,...patch}:item));
 const addFiles=(input:FileList|File[])=>{const files=Array.from(input); if(!files.length)return; const capacity=Math.max(0,6-uploads.length); if(files.length>capacity){flash(`最多同时保留 6 个文件，已忽略 ${files.length-capacity} 个`)} setImageError(''); files.slice(0,capacity).forEach(file=>{const lower=file.name.toLowerCase(); const isImage=file.type.startsWith('image/')||/\.(png|jpe?g|webp|gif)$/i.test(lower); const isDocument=/\.(pdf|csv|txt|md|json|doc|docx|xls|xlsx|ppt|pptx)$/i.test(lower)||file.type.startsWith('text/')||['application/pdf','application/json'].includes(file.type); const id=`upload-${Date.now()}-${uploadIdRef.current++}`; const tooLarge=file.size>15*1024*1024; const valid=isImage||isDocument; const previewUrl=isImage&&!tooLarge?URL.createObjectURL(file):undefined; const item:ImageMeta={id,kind:isImage?'image':'file',file_name:file.name,mime_type:file.type||'application/octet-stream',size_bytes:file.size,width:undefined,height:undefined,previewUrl,status:!valid||tooLarge?'error':isImage?'reading':'ready',progress:!valid||tooLarge?0:isImage?12:100,error:!valid?'格式不支持（支持图片、PDF、CSV、TXT、Office）':tooLarge?'文件超过 15MB 限制':undefined}; setUploads(prev=>[...prev,item]); if(isImage&&!tooLarge&&previewUrl){const probe=new Image(); probe.onload=()=>updateUpload(id,{width:probe.naturalWidth,height:probe.naturalHeight,status:'ready',progress:100}); probe.onerror=()=>updateUpload(id,{status:'error',progress:0,error:'图片无法读取，请重新选择'}); probe.src=previewUrl}})};
 const addUrl=()=>{const raw=imageUrlInput.trim(); if(!raw){setImageUrlError('请输入 http 或 https 网址');return} try{const parsed=new URL(raw); if(!['http:','https:'].includes(parsed.protocol))throw new Error('protocol'); if(uploads.length>=6){setImageUrlError('最多同时保留 6 个文件或网址');return} if(uploads.some(item=>item.kind==='url'&&item.url===parsed.toString())){setImageUrlError('该网址已在列表中');return} const id=`upload-${Date.now()}-${uploadIdRef.current++}`; setUploads(prev=>[...prev,{id,kind:'url',file_name:parsed.hostname+parsed.pathname,mime_type:'text/uri-list',size_bytes:0,url:parsed.toString(),status:'ready',progress:100}]); setImageUrlInput('');setImageUrlError('');setImageError('')}catch{setImageUrlError('网址格式无效，仅支持 http:// 或 https://')}};
 const removeUpload=(id:string)=>{const target=uploads.find(item=>item.id===id); if(target?.previewUrl)URL.revokeObjectURL(target.previewUrl); setUploads(prev=>prev.filter(item=>item.id!==id)); setImageAnalysis(prev=>prev.filter(item=>item.id!==id));};
 const clearUploads=()=>{uploads.forEach(item=>{if(item.previewUrl)URL.revokeObjectURL(item.previewUrl)});setUploads([]);setImageAnalysis([]);setImageError('');setImageUrlError('');};
