 const submitImageAnalysis=async()=>{const candidates=uploads.filter(item=>item.status==='ready'||item.status==='done'); if(!candidates.length){flash('请先添加至少一个可分析的图片、文件或网址');return} if(uploads.some(item=>item.status==='reading')){flash('图片仍在读取中，请稍候');return} setImageBusy(true);setImageError('');setImageAnalysis([]);setUploads(prev=>prev.map(item=>candidates.some(candidate=>candidate.id===item.id)?{...item,status:'analyzing',progress:25,error:undefined}:item)); const apiBase=process.env.NEXT_PUBLIC_API_URL||''; const items=candidates.map(item=>{const meta={...item}; if(meta.previewUrl)delete meta.previewUrl; return meta}); try{const response=await fetch(`${apiBase}/api/v1/image-analysis`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({asset,items})}); if(!response.ok)throw new Error('image analysis'); const payload=await response.json() as ImageBatchResult; const results=Array.isArray(payload.items)?payload.items:payload.title?[{...payload,id:candidates[0].id,file_name:candidates[0].file_name,kind:candidates[0].kind,provider:payload.provider||'demo_vision',mode:payload.mode||'演示分析',title:payload.title,conclusion:payload.conclusion||'',signals:payload.signals||[],next:payload.next||''}]:[]; if(!results.length)throw new Error('empty analysis'); const normalized=results.map((result,index)=>({...result,id:result.id||candidates[index]?.id,file_name:result.file_name||candidates[index]?.file_name,kind:result.kind||candidates[index]?.kind})); setImageAnalysis(normalized);setUploads(prev=>prev.map(item=>candidates.some(candidate=>candidate.id===item.id)?{...item,status:'done',progress:100}:item))}catch{setImageAnalysis(candidates.map(localAnalysis));setUploads(prev=>prev.map(item=>candidates.some(candidate=>candidate.id===item.id)?{...item,status:'done',progress:100}:item));setImageError('分析服务未连接，已自动显示本地结构化回退结果')}finally{setImageBusy(false)}};
 useEffect(()=>{if(!refresh)return; const id=setInterval(doRefresh,refresh*1000);return()=>clearInterval(id)},[refresh]);
 const currentSymbol=symbolMap[asset];
 useEffect(()=>{let cancelled=false; const apiBase=process.env.NEXT_PUBLIC_API_URL||''; setSnapshot(null); fetch(`${apiBase}/api/v1/market/${currentSymbol}`).then(r=>{if(!r.ok)throw new Error('market');return r.json()}).then((payload:unknown)=>{if(!cancelled){const data=payload as Snapshot;setSnapshot(data);setDataStatus(snapshotLabel(data))}}).catch(()=>{if(!cancelled)setDataStatus('静态演示（API 未连接）')}); return()=>{cancelled=true}},[currentSymbol,refreshTick]);
 useEffect(()=>{let cancelled=false; const apiBase=process.env.NEXT_PUBLIC_API_URL||''; const started=performance.now(); setSyncStatus('同步中');setSyncError(''); fetch(`${apiBase}/api/v1/market/board`,{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error('board');return r.json()}).then((payload:unknown)=>{if(cancelled)return; const data=payload as {items?:unknown;sync?:BoardSync}; const sync=data.sync;setGlobalQuotes(Array.isArray(data.items)?data.items as Snapshot[]:[]);setSyncLatency(typeof sync?.latency_ms==='number'?sync.latency_ms:Math.round(performance.now()-started));setLastSyncedAt(sync?.synced_at||new Date().toISOString());setSyncStatus('已同步')}).catch(()=>{if(!cancelled){setGlobalQuotes([]);setSyncLatency(Math.round(performance.now()-started));setSyncStatus('等待 API');setSyncError('交易数据接口未连接，当前看板保留演示值')}}); return()=>{cancelled=true}},[refreshTick]);
 useEffect(()=>{let cancelled=false; const apiBase=process.env.NEXT_PUBLIC_API_URL||''; setDomesticError(''); fetch(`${apiBase}/api/v1/public/domestic-delayed`,{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error('domestic');return r.json()}).then((payload:unknown)=>{if(cancelled)return; const data=payload as DomesticPayload; setDomesticQuotes(Array.isArray(data.items)?data.items:[]); setDomesticSync(data.sync||null)}).catch(()=>{if(!cancelled){setDomesticQuotes([]);setDomesticSync(null);setDomesticError('官方延时接口未连接，已保留待接入标签')}}); return()=>{cancelled=true}},[refreshTick]);
 const inspectPrivateSession=async(silent=false)=>{if(!silent)setPrivateMessage('正在检查私有版配置…'); const apiBase=process.env.NEXT_PUBLIC_API_URL||''; try{const response=await fetch(`${apiBase}/api/v1/private/session`,{cache:'no-store'}); const payload=await response.json().catch(()=>({})) as PrivateSessionPayload; if(response.status===503||payload.status==='private_auth_not_configured'){setPrivateAuth('not_configured');setPrivateSessionExpiresAt(''); if(!silent)setPrivateMessage(payload.message||'私有版尚未配置'); return} if(response.ok&&payload.authenticated){setPrivateAuth('logged_in');setPrivateSessionExpiresAt(payload.expires_at||''); if(!silent)setPrivateMessage('会话有效 · 仅当前浏览器')}else{setPrivateAuth('logged_out');setPrivateSessionExpiresAt(''); if(!silent)setPrivateMessage(payload.message||'已配置，请输入本人访问码')}}catch{setPrivateAuth('logged_out');setPrivateSessionExpiresAt(''); if(!silent)setPrivateMessage('检查接口暂时不可用，请稍后重试')}};
 useEffect(()=>{void inspectPrivateSession(true)},[]);
 const loginPrivate=async()=>{if(!privateCode.trim()){setPrivateMessage('请输入本人访问码');return} setPrivateMessage('验证中…'); const apiBase=process.env.NEXT_PUBLIC_API_URL||''; try{const response=await fetch(`${apiBase}/api/v1/private/session`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({access_code:privateCode})}); const payload=await response.json().catch(()=>({})) as PrivateSessionPayload; if(payload.status==='private_auth_not_configured'||response.status===503){setPrivateAuth('not_configured');setPrivateSessionExpiresAt('');setPrivateMessage(payload.message||'私有版尚未配置');return} if(!response.ok||!payload.authenticated){setPrivateAuth('logged_out');setPrivateSessionExpiresAt('');setPrivateMessage(payload.message||'访问码不正确');return} setPrivateCode('');setPrivateAuth('logged_in');setPrivateSessionExpiresAt(payload.expires_at||'');setPrivateMessage('已登录 · 仅当前浏览器会话');}catch{setPrivateMessage('登录接口暂时不可用，请稍后重试')}};
 const logoutPrivate=async()=>{const apiBase=process.env.NEXT_PUBLIC_API_URL||''; await fetch(`${apiBase}/api/v1/private/session`,{method:'DELETE'}).catch(()=>undefined); setPrivateAuth('logged_out');setPrivateSessionExpiresAt('');setCtpPayload(null);setPrivateMessage('已退出私有版');};
 const refreshPrivateQuotes=()=>{if(privateAuth!=='logged_in')return; setPrivateMessage('正在刷新 CTP 行情…'); setPrivateRefreshTick(t=>t+1)};
 useEffect(()=>{if(privateAuth!=='logged_in'){setCtpPayload(null);setCtpStatus('idle');return} let cancelled=false; const apiBase=process.env.NEXT_PUBLIC_API_URL||''; setCtpStatus('loading'); fetch(`${apiBase}/api/v1/private/ctp/board`,{cache:'no-store'}).then(async response=>{const payload=await response.json().catch(()=>({status:'ctp_bridge_error'})) as CtpPayload; if(cancelled)return; if(response.status===401){setPrivateAuth('logged_out');setPrivateSessionExpiresAt('');setCtpPayload(null);setCtpStatus('idle');setPrivateMessage('会话已失效，请重新登录');return} setCtpPayload(payload); setCtpStatus(response.ok?'ready':'error')}).catch(()=>{if(!cancelled){setCtpPayload({status:'ctp_bridge_error',note:'CTP Bridge 暂时不可用'});setCtpStatus('error')}}); return()=>{cancelled=true}},[privateAuth,privateRefreshTick]);
 const activeSnapshot=snapshot?.symbol===currentSymbol?snapshot:null;
 const activeCurrency=snapshotCurrency(asset,activeSnapshot);
 const active={price:activeSnapshot?.price?.toLocaleString('en-US',{maximumFractionDigits:3})||assets[asset].price,change:typeof activeSnapshot?.change_pct==='number'?`${activeSnapshot.change_pct>=0?'+':''}${activeSnapshot.change_pct.toFixed(2)}%`:'—'};
 const liveQuote=(name:Asset)=>globalQuotes.find(q=>q.symbol===symbolMap[name]);
 const quoteChange=(name:Asset)=>{const q=liveQuote(name); return typeof q?.change_pct==='number'?`${q.change_pct>=0?'+':''}${q.change_pct.toFixed(2)}%`:'—';};
 const boardQuote=(name:Asset):Snapshot=>liveQuote(name)||{symbol:symbolMap[name],name,price:quoteNumber(assets[name].price),change_pct:null,currency:assetCurrency(name),provider:'demo',data_mode:'demo_fallback',delayed:true,as_of:''};
 const boardLiveCount=focusAssets.filter(name=>isLiveMode(liveQuote(name))).length;
 const boardFreshness=syncStatus==='已同步'?(boardLiveCount?`${boardLiveCount}/6 实时源 · ${formatSyncTime(lastSyncedAt)}`:`已同步 · ${formatSyncTime(lastSyncedAt)}`):syncStatus;
 const refreshText=refresh<60?`每 ${refresh} 秒`:refresh===60?'每 1 分钟':`每 ${refresh/60} 分钟`;
 const currentPlan=currentPlans[asset];
 const currentCalendar=calendarForAsset(asset);
 const liveRailEvents=useMemo(()=>dynamicEvents.filter(e=>e.asset===asset).slice(0,2),[asset,dynamicEvents]);
 const goldQuote=globalQuotes.find(q=>q.symbol==='gold')?.price||2654.8; const silverQuote=globalQuotes.find(q=>q.symbol==='silver')?.price||31.642; const goldSilverRatio=goldQuote/silverQuote; const ratioTone=goldSilverRatio>=85?'白银相对偏弱':goldSilverRatio<=75?'白银相对强势':'中性偏高'; const ratioAction=goldSilverRatio>=85?'黄金防守、白银等待比值回落再加仓':goldSilverRatio<=75?'白银弹性占优，黄金仓位需防相对落后':'等待比值确认方向，控制白银追涨仓位';
 const eventFactor=filtered.length?Math.round(filtered.reduce((sum,e)=>sum+(e.side==='利多'?e.confidence:e.side==='利空'?100-e.confidence:50),0)/filtered.length):45;
 const macroFactor=asset==='黄金'&&goldSilverRatio>=85?Math.min(100,assets[asset].score+6):asset==='白银'&&goldSilverRatio<=75?Math.min(100,assets[asset].score+8):assets[asset].score;
 const catalystFactor=timelineEvents.length?Math.round(timelineEvents.slice(0,4).reduce((sum,e)=>sum+(e.impact==='高'?72:e.impact==='中'?58:50),0)/Math.min(4,timelineEvents.length)):45;
 const dataFactor=activeSnapshot?isLiveMode(activeSnapshot)?88:isPublicDelayed(activeSnapshot)?72:55:globalQuotes.length?58:35;
 const scoreFactors=[
  {label:'趋势与价位',score:assets[asset].score,weight:30,evidence:`多空强度 ${assets[asset].score}/100 · ${assets[asset].tone}`},
  {label:'宏观与相关性',score:macroFactor,weight:20,evidence:`金银比 ${goldSilverRatio.toFixed(2)} · ${assetContext[asset].verify}`},
  {label:'事件催化',score:eventFactor,weight:20,evidence:`${filtered.length} 条已排序资讯 · ${eventSyncStatus}`},
  {label:'资金与库存',score:Math.round((assets[asset].score+eventFactor)/2),weight:15,evidence:assetContext[asset].catalyst},
  {label:'数据可用性',score:dataFactor,weight:15,evidence:activeSnapshot?snapshotLabel(activeSnapshot):'等待 Provider 返回'},
 ];
 const weekScore=Math.round(scoreFactors.reduce((sum,factor)=>sum+factor.score*factor.weight/100,0));
 const weekBand=decisionBand(weekScore); const weekTone=decisionTone(weekScore);
 const scenarioRows=[
  {label:'基准路径',tone:'base',text:`${weekBand}，${currentPlan.action}`,trigger:currentPlan.trigger},
  {label:'上行情景',tone:'bull',text:`催化剂兑现后顺势跟踪：${assetContext[asset].catalyst}`,trigger:'价格、宏观与资金信号同向'},
  {label:'下行情景',tone:'bear',text:`先防守并降低杠杆：${assetContext[asset].risk}`,trigger:`失效条件：${currentPlan.invalid}`},
 ];
 useEffect(()=>{let cancelled=false; const apiBase=process.env.NEXT_PUBLIC_API_URL||''; queueMicrotask(()=>{if(!cancelled){setCandleStatus('loading');setCandleError('');setCandles(null)}}); const url=`${apiBase}/api/v1/market/candles?symbol=${encodeURIComponent(currentSymbol)}&interval=${candleInterval}`; fetch(url,{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error('candles');return r.json()}).then((payload:unknown)=>{if(cancelled)return; const data=payload as Partial<CandlePayload>; if(!Array.isArray(data.candles)||data.candles.length<2)throw new Error('candles empty'); setCandles(data as CandlePayload);setCandleStatus('ready')}).catch(()=>{if(!cancelled){setCandles(demoCandles(currentSymbol,candleInterval));setCandleStatus('error');setCandleError('K线接口未连接，已自动显示本地演示形态')}});return()=>{cancelled=true}},[currentSymbol,candleInterval,refreshTick]);
 const candleView=useMemo(()=>{const rows=(candles?.candles||[]).filter(c=>[c.open,c.high,c.low,c.close].every(value=>Number.isFinite(value))).slice(-48); if(!rows.length)return {rows:[],min:0,max:1,y:()=>0,left:26,width:848,bottom:258}; const min=Math.min(...rows.map(c=>c.low)); const max=Math.max(...rows.map(c=>c.high)); const span=max-min||Math.max(Math.abs(max)*.01,1); const top=20; const bottom=258; const height=bottom-top; const left=26; const width=848; const step=width/Math.max(rows.length,1); const y=(value:number)=>top+((max-value)/span)*height; return {rows:rows.map((c,i)=>{const x=left+step*(i+.5);const bodyTop=y(Math.max(c.open,c.close));const bodyBottom=y(Math.min(c.open,c.close));return {...c,x,w:Math.max(4,step*.56),wickTop:y(c.high),wickBottom:y(c.low),bodyTop,bodyHeight:Math.max(2,bodyBottom-bodyTop),up:c.close>=c.open}}),min,max,y,left,width,bottom};},[candles]);
 const uploadReadyCount=uploads.filter(item=>item.status==='ready'||item.status==='done').length;
 const uploadOverall=uploads.length?Math.round(uploads.reduce((sum,item)=>sum+item.progress,0)/uploads.length):0;
 const candleCurrency=candles?.currency||activeCurrency;
 const uploadStatusText=(item:ImageMeta)=>item.status==='reading'?'读取中':item.status==='analyzing'?'分析中':item.status==='done'?'已完成':item.status==='error'?'失败':item.status==='ready'?'待提交':'已加入';
 const uploadIcon=(item:ImageMeta)=>item.kind==='image'?'▧':item.kind==='url'?'↗':'▤';
 useEffect(()=>{const onKey=(e:KeyboardEvent)=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector<HTMLInputElement>('.search input')?.focus()} if(e.key==='Escape')setSelected(null)};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey)},[]);
 return <div className={`${dark?'app dark':'app'}${compact?' compact':''}`}>
  <header className="topbar"><button className="mobile-menu" onClick={()=>setMobileNav(!mobileNav)} aria-label="打开导航">☰</button><div className="brand"><span className="brand-mark">◆</span><div><b>期鉴</b><small>FUTURES INTELLIGENCE</small></div></div><label className="search"><span>⌕</span><input value={query} onFocus={()=>setSearchOpen(true)} onChange={e=>{setQuery(e.target.value);setSearchOpen(true)}} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();submitSearch()}if(e.key==='Escape')setSearchOpen(false)}} placeholder="搜索其他品种、合约或关键词…"/><button type="button" className="search-submit" onClick={submitSearch} aria-label="回车搜索" title="回车搜索">回车</button><kbd>⌘ K</kbd>{searchOpen&&query&&<div className="search-results">{assetOptions.length?assetOptions.map(x=><button type="button" key={x} onMouseDown={e=>e.preventDefault()} onClick={()=>chooseAsset(x)}><span className={`mini-dot ${x===asset?'on':''}`}/><b>{x}</b><small>{assets[x].symbol}</small><em>切换分析</em></button>):<p>暂无匹配品种，可继续输入关键词筛选资讯</p>}</div>}</label><div className="top-actions"><span className="live"><i/>实时</span><button onClick={()=>setDark(!dark)} aria-label="切换主题">{dark?'☼':'◐'}</button><button className="avatar">Q</button></div></header>
  <aside className={mobileNav?'sidebar open':'sidebar'}><nav><span className="nav-label">工作台</span><a className="active" href="#overview">▦<b>市场总览</b></a><a href="#decision">◉<b>一周决策摘要</b></a><a href="#live-board">◈<b>国际行情</b></a><a href="#public-data">▣<b>国内官方延时</b></a><a href="#private-data">▰<b>本人 CTP 私有版</b></a><a href="#kline">◒<b>实时K线</b></a><a href="#intel">⌁<b>资讯雷达</b><em>12</em></a><a href="#changes">⌇<b>变化追踪</b><em className="orange">5</em></a><a href="#timeline">▥<b>策略日历</b></a><span className="nav-label">重点品种</span>{focusAssets.map((x,i)=><button key={x} className={asset===x?'asset active':'asset'} onClick={()=>{setAsset(x);setMobileNav(false)}}><span className={`dot d${i}`}/><b>{x}</b><small>{assets[x].symbol}</small></button>)}<span className="nav-label">工具</span><a href="#risk">⌗<b>风险中心</b></a><a href="#platforms">◎<b>平台对标</b></a><a href="#official">⚙<b>官方入口</b></a></nav><div className="system"><div><span>系统状态</span><b>全部正常</b></div><p><i/><span>数据延迟</span><b>1.2s</b></p><p><i/><span>来源在线</span><b>8 / 8</b></p></div></aside>
  <main><section id="overview" className="headline"><div><p className="eyebrow">市场情报中心 <span>北京时间 {beijingTime||'---- -- -- --:--:--'} · 实时</span></p><h1>{asset} <small>{assets[asset].symbol}</small></h1><p>聚合全球重要动态，结合宏观、技术与资金面生成可解释研判</p></div><div className="refresh"><span>更新于 {updated} · 延迟 1.2s</span><select value={refresh} onChange={e=>setRefresh(+e.target.value)} aria-label="自动刷新间隔"><option value="10">每 10 秒</option><option value="20">每 20 秒</option><option value="30">每 30 秒</option><option value="60">每 1 分钟</option><option value="180">每 3 分钟</option><option value="300">每 5 分钟</option><option value="600">每 10 分钟</option><option value="900">每 15 分钟</option><option value="1800">每 30 分钟</option><option value="3600">每 60 分钟</option></select><button onClick={doRefresh}>↻ 立即刷新</button><button className={alerts?'tool-active':''} onClick={()=>{setAlerts(!alerts);setToast(alerts?'已暂停事件提醒':'已开启事件提醒')}}>♧ {alerts?'提醒中':'提醒已停'}</button><button onClick={()=>setCompact(!compact)}>▤ {compact?'舒展':'紧凑'}</button></div></section>
   <section id="timeline" className="event-rail"><div className="rail-title"><span>事件日历 / 全球事件</span><small>未来 24 小时 · 北京时间 · 按影响排序</small><small className="event-rail-sync">全球事件 {eventSyncStatus}</small></div>{liveRailEvents.map(e=><button key={`live-${e.id}`} onClick={()=>setSelected(e)}><b>{e.time}</b><span>{e.title}</span><em className={e.side==='利空'?'negative':e.side==='利多'?'high':''}>{e.side}</em><small>{e.source}</small></button>)}{currentCalendar.slice(0,Math.max(0,3-liveRailEvents.length)).map(c=><button key={c[0]} onClick={()=>setShowCalendar(true)}><b>{c[0]}</b><span>{c[1]}</span><em className={c[2]==='高'?'high':''}>{c[2]}</em><small>{c[3]}</small></button>)}<button className="rail-more" onClick={()=>setShowCalendar(!showCalendar)}>{showCalendar?'收起日历':'查看完整日历'} →</button></section>
   {showCalendar&&<section className="calendar-panel"><div className="calendar-head"><div><h2>高影响事件窗口 · {asset}</h2><p>用于管理持仓风险，时间均为北京时间</p></div><span>提醒 {alerts?'已开启':'已暂停'}</span></div><div className="calendar-grid">{currentCalendar.map(c=><div key={c[0]}><b>{c[0]}</b><div><strong>{c[1]}</strong><small>{c[3]}</small></div><em className={c[2]==='高'?'high':''}>{c[2]}影响</em></div>)}</div></section>}
   <section id="pulse" className="metrics"><div className="price-card"><span>主力参考价 · {currencyLabel(activeCurrency)}</span><div><strong>{active.price}<small className="currency-tag">{currencyShort(activeCurrency)}</small></strong><b>{active.change}</b></div><small>参考区间 {assetContext[asset].range} · {currencyShort(activeCurrency)}</small><div className="spark"><i/><i/><i/><i/><i/><i/><i/><i/><i/><i/></div></div><div><span>多空强度</span><strong className="amber">{assets[asset].score}</strong><b>/ 100 · {assets[asset].tone}</b><div className="bar"><i style={{width:`${assets[asset].score}%`}}/></div><small>较昨日 <em>↑ 6</em></small></div><div><span>关键事件</span><strong>{filtered.length||2}</strong><b>条高价值动态</b><small><em>▲ {filtered.filter(e=>e.side==='利多').length} 利多</em>　<span className="bear">▼ {filtered.filter(e=>e.side==='利空').length} 利空</span></small></div><div><span>研判置信度</span><strong>{Math.round(filtered.reduce((sum,e)=>sum+e.confidence,0)/(filtered.length||1))}%</strong><b>跨来源验证</b><small>{filtered.length?`${filtered.length} 条已纳入`:'等待数据'} · {dataStatus}</small></div></section>
   <section id="decision" className="decision-panel panel"><div className="panel-head"><div><h2>一周决策摘要 · 100 分制研究评分</h2><p>把趋势、宏观、事件、资金与数据质量压缩成一眼可读的条件信号</p></div><div className={`decision-score ${weekTone}`}><strong>{weekScore}</strong><span>/ 100</span><b>{weekBand}</b></div></div><div className="decision-disclaimer"><span>当前品种：{asset} · 研究窗口：未来 7 日</span><b>不等于胜率，不构成收益保证；必须等触发条件与失效条件验证</b></div><div className="decision-body"><div className="factor-list">{scoreFactors.map(factor=><div className="factor-row" key={factor.label}><div><b>{factor.label}</b><small>{factor.evidence}</small></div><strong>{factor.score}</strong><span><i style={{width:`${factor.score}%`}}/></span><em>权重 {factor.weight}</em></div>)}</div><div className="scenario-grid">{scenarioRows.map(row=><article className={`scenario ${row.tone}`} key={row.label}><span>{row.label}</span><p>{row.text}</p><small>确认：{row.trigger}</small></article>)}</div></div><div className="decision-footer"><span>执行优先级：{currentPlan.bias} · 单品种风险 {currentPlan.size}</span><span>数据状态：{dataStatus} · 事件同步：{eventSyncStatus}</span><a href="#strategy">查看 7 日路径 →</a></div></section>
   <section className="ratio-panel panel"><div className="ratio-main"><div><span>金银比 Gold / Silver · USD / 美元</span><strong>{goldSilverRatio.toFixed(2)}</strong><small>黄金 {goldQuote.toLocaleString('en-US',{maximumFractionDigits:3})} <i className="currency-tag">USD</i> ÷ 白银 {silverQuote.toLocaleString('en-US',{maximumFractionDigits:3})} <i className="currency-tag">USD</i></small></div><b className="ratio-badge">{ratioTone}</b></div><div className="ratio-meter"><i style={{width:`${Math.min(100,Math.max(0,(goldSilverRatio-60)*4))}%`}}/></div><div className="ratio-analysis"><div><span>趋势解读</span><p>比值上行：黄金相对占优、风险偏好偏弱；比值下行：白银相对占优、工业需求与风险偏好改善。</p></div><div><span>当前投资倾向</span><p>{ratioAction}</p></div><div><span>验证条件</span><p>结合美元、实际利率、COMEX / LME 库存与 CFTC 净持仓；金银比不单独作为开仓信号。</p></div></div></section>
   <section id="image-analysis" className={`image-lab panel ${uploads.some(item=>item.status==='error')?'has-error':''}`}><div className="panel-head"><div><h2>图片辅助分析</h2><p>可一次添加多张图片、PDF/CSV/TXT/Office 文件或网址，确认后统一分析</p></div><span className="image-limit">图片 ≤ 15MB · 最多 6 项 · 仅提交结构化信息</span></div><div className="upload-toolbar"><label className="upload-box" onDrop={e=>{e.preventDefault();addFiles(e.dataTransfer.files)}} onDragOver={e=>e.preventDefault()}><input type="file" multiple accept="image/*,.pdf,.csv,.txt,.md,.json,.doc,.docx,.xls,.xlsx,.ppt,.pptx" onChange={e=>{if(e.currentTarget.files)addFiles(e.currentTarget.files);e.currentTarget.value=''}}/><span className="upload-icon">＋</span><b>添加图片或文件</b><small>拖拽或点击，支持多选</small><em>{uploads.length?`${uploadReadyCount}/${uploads.length} 项可提交`:'等待添加'}</em></label><div className="url-input-box"><label htmlFor="analysis-url">添加网址</label><div><input id="analysis-url" value={imageUrlInput} onChange={e=>{setImageUrlInput(e.target.value);setImageUrlError('')}} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();addUrl()}}} placeholder="https://example.com/资讯或报告"/><button type="button" onClick={addUrl}>加入网址</button></div>{imageUrlError&&<small className="upload-inline-error">{imageUrlError}</small>}<p>仅允许 http:// 或 https://；加入后可在列表中确认。</p></div><div className="upload-progress-card"><div><b>上传队列</b><strong>{uploadOverall}%</strong></div><div className="upload-progress"><i style={{width:`${uploadOverall}%`}}/></div><small>{uploads.length?`${uploads.length} 项 · ${imageBusy?'正在分析':'等待确认提交'}`:'还没有添加文件或网址'}</small></div></div>{uploads.length?<div className="upload-queue" aria-live="polite">{uploads.map(item=><article className={`upload-item upload-${item.status}`} key={item.id}>{item.kind==='image'&&item.previewUrl?<img src={item.previewUrl} alt={`${item.file_name} 预览`} onError={()=>updateUpload(item.id,{status:'error',progress:0,error:'图片预览加载失败'})}/>:<span className="upload-file-icon">{uploadIcon(item)}</span>}<div className="upload-item-main"><div className="upload-item-title"><b>{item.file_name}</b><span>{item.kind==='url'?'网址':item.mime_type||'文件'}{item.size_bytes?` · ${(item.size_bytes/1024).toFixed(0)} KB`:''}{item.width&&item.height?` · ${item.width}×${item.height}`:''}</span></div><div className="upload-item-progress"><i style={{width:`${item.progress}%`}}/><em>{uploadStatusText(item)}{item.status!=='error'?` ${item.progress}%`:''}</em></div>{item.error&&<small className="upload-item-error">{item.error}</small>}</div><div className="upload-item-actions">{item.kind==='url'&&item.url?<a href={item.url} target="_blank" rel="noreferrer">打开</a>:null}<button type="button" onClick={()=>removeUpload(item.id)}>移除</button></div></article>)}</div>:<div className="image-empty"><span>⌁</span><p>添加后会立即显示缩略图、尺寸、进度与识别状态；不会自动提交。</p></div>}<div className="upload-actions"><span>提交前确认：文件只用于本次分析，不会保存到公开页面。</span><div><button type="button" className="upload-ghost" disabled={!uploads.length||imageBusy} onClick={clearUploads}>清空</button><button type="button" className="upload-submit" disabled={!uploadReadyCount||imageBusy||uploads.some(item=>item.status==='reading')} onClick={()=>void submitImageAnalysis()}>{imageBusy?`分析中 ${uploadOverall}%`:`确认并分析（${uploadReadyCount}）`}</button></div></div>{imageAnalysis.length>0&&<div className="upload-results"><div className="result-head"><b>分析结果 · {imageAnalysis.length} 项</b><span>{imageAnalysis[0].mode}</span></div>{imageAnalysis.map(result=><article key={result.id||result.file_name||result.title}><b>{result.file_name||result.title}</b><p>{result.conclusion}</p><ul>{result.signals.map(signal=><li key={signal}>✓ {signal}</li>)}</ul><small>{result.next}</small></article>)}</div>}{imageError&&<div className="upload-analysis-error" role="alert">{imageError}</div>}</section>
   <section className="compare-strip"><div className="compare-title"><span>跨品种速览</span><small>重点六品种 · {globalQuotes.length?'免费源同步':'等待 API'}</small></div>{focusAssets.map(x=><button key={x} className={x===asset?'chosen':''} onClick={()=>setAsset(x)}><span className={`mini-dot ${x===asset?'on':''}`}/><b>{x}</b><strong>{quoteChange(x)}</strong><small>{assets[x].tone}</small></button>)}<button className="quality-btn" onClick={()=>setShowQuality(!showQuality)} aria-expanded={showQuality}>100点优化 {showQuality?'收起':'展开'}</button></section>
   <section id="live-board" className="trade-board panel"><div className="panel-head"><div><h2>国际现货与宏观看板</h2><p>公开版优先展示国际现货/外汇实时；日频、授权和演示状态逐项标注</p></div><div className="board-actions"><span className={`sync-pill ${syncStatus==='已同步'?'ok':''}`}><i/>{syncStatus}</span><span className="sync-meta">{syncError||`${boardFreshness} · ${syncLatency===null?'—':`${syncLatency} ms`}`}</span><button onClick={doRefresh}>↻ 同步行情</button></div></div><div className="board-kpis"><div><span>可用实时源</span><strong>{boardLiveCount}<small>/ 6</small></strong><em>{boardLiveCount?'国际现货 / 外汇':'等待配置免费 Key'}</em></div><div><span>同步方式</span><strong>轮询</strong><em>{refreshText} · 服务端缓存 {15}s</em></div><div><span>数据纪律</span><strong>不伪装</strong><em>国内期货请看下方官方延时表</em></div></div><div className="board-table-wrap"><table className="board-table"><thead><tr><th>品种</th><th>最新价（单位）</th><th>涨跌</th><th>数据状态</th><th>更新时间</th><th>来源</th></tr></thead><tbody>{focusAssets.map(name=>{const live=liveQuote(name);const quote=boardQuote(name);const hasApiRow=Boolean(live);const currency=snapshotCurrency(name,quote);const change=typeof quote.change_pct==='number'?`${quote.change_pct>=0?'+':''}${quote.change_pct.toFixed(2)}%`:hasApiRow?'—':assets[name].change;const mode=hasApiRow?snapshotLabel(quote):'API 未连接 · 演示值';return <tr key={name} className={name===asset?'selected-row':''} onClick={()=>setAsset(name)} tabIndex={0} onKeyDown={e=>e.key==='Enter'&&setAsset(name)}><td><span className="board-dot"/><b>{name}</b><small>{assets[name].symbol}</small></td><td className="board-price"><span>{formatPrice(quote.price)}</span><small className="currency-tag">{currencyShort(currency)}</small></td><td className={change.startsWith('-')?'negative':'positive'}>{change}</td><td><span className={`board-mode ${boardModeClass(quote)}`}><i/>{mode}</span></td><td>{hasApiRow&&quote.data_mode!=='demo_fallback_no_key'?formatSyncTime(quote.as_of||undefined):'—'}</td><td>{hasApiRow&&quote.source_url?<a href={quote.source_url} target="_blank" rel="noreferrer" onClick={e=>e.stopPropagation()}>来源 ↗</a>:<span className="muted-cell">—</span>}</td></tr>})}</tbody></table></div><div className="board-foot"><span><i className="live-dot"/>价格单位已明确：美元/人民币或指数点；“实时”仅代表 Provider 返回明确实时的国际现货 / 外汇。</span><span>同步时间：{formatSyncTime(lastSyncedAt)} · {syncStatus}</span></div></section>
   <section id="public-data" className="public-data panel"><div className="panel-head"><div><h2>公开版 · 官方延时国内期货</h2><p>默认读取上期所官网公开 JSON；只展示允许公开的延时字段，不把延时数据冒充实时</p></div><span className="mode-badge public">公开版</span></div><div className="public-policy"><span><i className="delayed-dot"/>官方延时行情 · CNY / 人民币</span><span>同步：{domesticSync?.synced_at?formatSyncTime(domesticSync.synced_at):'等待同步'}</span><span>{domesticSync?.delayed_count||0}/{domesticSync?.item_count||domesticAssets.length} 条可用</span><a href="https://www.shfe.com.cn/reports/marketdata/delayedquotes/" target="_blank" rel="noreferrer">官方说明 ↗</a><a href="https://www.shfe.com.cn/data/tradedata/future/delaymarket/delaymarket_all.dat" target="_blank" rel="noreferrer">JSON ↗</a></div><div className="public-table-wrap"><table className="public-table"><thead><tr><th>品种 / 合约</th><th>最新价（CNY）</th><th>涨跌</th><th>数据标签</th><th>时间（北京时间）</th><th>来源</th></tr></thead><tbody>{domesticAssets.map(def=>{const quote=domesticQuotes.find(item=>item.symbol===def.symbol)||{symbol:def.symbol,name:def.name,contract:def.contract,price:null,change_pct:null,currency:'CNY',provider:'shfe_official_delayed',data_mode:'official_delayed_config_required',delayed:true,available:false,source_url:'https://www.shfe.com.cn/reports/marketdata/delayedquotes/'} as Snapshot; const label=snapshotLabel(quote); const change=formatChange(quote.change_pct); return <tr key={def.symbol} onClick={()=>setAsset(def.asset)} className={asset===def.asset?'selected-row':''}><td><b>{quote.name||def.name}</b><small>{quote.contract||def.contract}</small></td><td className="board-price"><span>{formatPrice(quote.price)}</span><small className="currency-tag">CNY</small></td><td className={change.startsWith('-')?'negative':'positive'}>{change}</td><td><span className={`board-mode ${boardModeClass(quote)}`}><i/>{label}</span></td><td>{quote.as_of?formatSyncTime(quote.as_of):'待接入'}</td><td>{quote.source_url?<a href={quote.source_url} target="_blank" rel="noreferrer" onClick={e=>e.stopPropagation()}>来源 ↗</a>:<span className="muted-cell">—</span>}</td></tr>})}</tbody></table></div><div className="public-foot"><span>{domesticError||'国内期货公开版不含实时 Tick、Level-2 盘口或自动下单。'}</span><span>默认源：上期所官网公开 JSON · 服务端缓存 60s</span></div></section>
   <section id="private-data" className="private-data panel">
    <div className="panel-head"><div><h2>私有版 · 本人 CTP 实时行情</h2><p>服务端访问码 + HttpOnly 会话；只向本人会话返回 CTP Bridge 数据</p></div><span className="mode-badge private">私有版 · CNY</span></div>
    <div className="private-guide">
      <div className="private-guide-head"><div><strong>本人专属接入流程</strong><span>访问码和 CTP 行情均只在服务端处理，不会出现在公开页面</span></div><span className="private-security">HttpOnly · 8 小时会话</span></div>
      <ol>
        <li><b>配置访问码</b><span>EdgeOne → 项目设置 → 环境变量，新增 PRIVATE_ACCESS_CODE（强随机值），保存后重新部署。</span></li>
        <li><b>接入 Bridge</b><span>在中国大陆自有主机运行 CTP Bridge，配置 CTP_BRIDGE_URL；可选 CTP_BRIDGE_TOKEN。Bridge 只返回本人行情。</span></li>
        <li><b>登录同步</b><span>刷新本页，输入访问码登录；登录后点击“刷新 CTP 行情”，退出或 8 小时后会话失效。</span></li>
      </ol>
      <details className="private-contract"><summary>查看 CTP Bridge 返回格式</summary><pre>{'{\n  "items": [{"symbol":"au","name":"沪金","contract":"AU主连","last":0,"bid":0,"ask":0,"change_pct":0,"volume":0,"open_interest":0,"as_of":"2026-09-05T01:00:00Z"}],\n  "as_of": "2026-09-05T01:00:00Z",\n  "latency_ms": 120\n}'}</pre></details>
    </div>
    {privateAuth==='unknown'?<div className="private-state"><strong>正在检查私有版配置…</strong><p>正在验证访问码配置状态，不会请求 CTP 行情。</p><button type="button" className="private-ghost" onClick={()=>void inspectPrivateSession()}>重新检查</button></div>:privateAuth==='not_configured'?<div className="private-state"><strong>第 1 步未完成：尚未配置 PRIVATE_ACCESS_CODE</strong><p>请按上方流程在 EdgeOne 项目设置中添加环境变量并重新部署；配置完成后点击“重新检查配置”。</p><button type="button" className="private-ghost" onClick={()=>void inspectPrivateSession()}>重新检查配置</button></div>:privateAuth!=='logged_in'?<form className="private-login" onSubmit={e=>{e.preventDefault();void loginPrivate()}}><div className="private-login-status"><i/>第 2 步：输入访问码登录</div><label>本人访问码<input type="password" autoComplete="current-password" value={privateCode} onChange={e=>setPrivateCode(e.target.value)} placeholder="仅发送到当前域名的服务端"/></label><button type="submit">登录私有版</button><span>{privateMessage||'已检测到访问码配置；未登录时不会请求 CTP 行情。'}</span></form>:<div className="private-session"><div className="private-session-head"><div><strong>已登录 · 仅限本人</strong><span>CTP 实时数据不会出现在公开版 · 价格单位 CNY / 人民币 · 会话至 {privateSessionExpiresAt?formatBeijingDateTime(privateSessionExpiresAt):'未知'}（北京时间） · 最近同步 {ctpPayload?.as_of?formatBeijingDateTime(ctpPayload.as_of):'等待同步'}（北京时间）</span></div><div className="private-session-actions"><button type="button" className="private-refresh" onClick={refreshPrivateQuotes} disabled={ctpStatus==='loading'}>↻ {ctpStatus==='loading'?'同步中':'刷新 CTP 行情'}</button><button type="button" onClick={()=>void logoutPrivate()}>退出</button></div></div>{ctpStatus==='loading'?<div className="private-state"><strong>正在同步 CTP Bridge…</strong><p>只读取当前会话允许的合约，完成后会显示北京时间和 CNY 单位。</p></div>:ctpPayload?.items?.length?<div className="ctp-table-wrap"><table className="ctp-table"><thead><tr><th>合约</th><th>最新（CNY）</th><th>买一 / 卖一（CNY）</th><th>涨跌</th><th>成交量 / 持仓</th><th>时间（北京时间）</th></tr></thead><tbody>{ctpPayload.items.map(item=><tr key={item.symbol+'-'+item.contract}><td><b>{item.name}</b><small>{item.contract}</small></td><td>{formatPrice(item.last)} <small className="currency-tag">CNY</small></td><td>{formatPrice(item.bid)} / {formatPrice(item.ask)} <small className="currency-tag">CNY</small></td><td className={(item.change_pct||0)<0?'negative':'positive'}>{formatChange(item.change_pct)}</td><td>{formatPrice(item.volume)} / {formatPrice(item.open_interest)}</td><td>{item.as_of?formatBeijingDateTime(item.as_of):ctpPayload.as_of?formatBeijingDateTime(ctpPayload.as_of):'—'}</td></tr>)}</tbody></table></div>:<div className="private-state"><strong>{ctpPayload?.status==='ctp_bridge_not_configured'?'第 2 步未完成：CTP Bridge 尚未配置':ctpPayload?.status==='ok'?'Bridge 已连接，但暂无可用合约':'CTP 行情暂不可用'}</strong><p>{ctpPayload?.note||'请配置 CTP_BRIDGE_URL，让服务端从本人 Bridge 拉取实时行情；Bridge 必须使用 HTTPS。'}</p><div className="private-error-actions"><button type="button" className="private-ghost" onClick={refreshPrivateQuotes}>↻ 重试同步</button>{privateMessage&&<small>{privateMessage}</small>}</div></div>}</div>}
  </section>
   <section id="kline" className="kline-panel panel"><div className="panel-head kline-head"><div><h2>实时交易 K 线</h2><p>当前价随看板同步；免费源按可用周期展示历史 K 线</p></div><div className="kline-actions"><span className={`kline-mode ${candles?.is_live?'live':''}`}><i/>{candles?.data_label||'等待K线同步'}</span><select value={candleInterval} onChange={e=>setCandleInterval(e.target.value as 'daily'|'weekly'|'monthly')} aria-label="K线周期"><option value="daily">日K</option><option value="weekly">周K</option><option value="monthly">月K</option></select><button onClick={doRefresh}>↻ 刷新</button></div></div><div className="kline-summary"><div><span>最新收盘/报价 · {currencyLabel(candleCurrency)}</span><strong>{candleView.rows.length?candleView.rows[candleView.rows.length-1].close.toLocaleString('en-US',{maximumFractionDigits:3}):'—'} <small className="currency-tag">{currencyShort(candleCurrency)}</small></strong><small>{candles?.as_of?`更新时间 ${formatSyncTime(candles.as_of)}`:'等待同步'}</small></div><div><span>区间高点 · {currencyShort(candleCurrency)}</span><b>{candleView.rows.length?candleView.max.toLocaleString('en-US',{maximumFractionDigits:3}):'—'}</b></div><div><span>区间低点 · {currencyShort(candleCurrency)}</span><b>{candleView.rows.length?candleView.min.toLocaleString('en-US',{maximumFractionDigits:3}):'—'}</b></div><div><span>当前品种</span><b>{asset} · {assets[asset].symbol}</b></div></div><div className="kline-chart-wrap">{candleStatus==='loading'?<div className="kline-empty">正在同步 {asset} K 线…</div>:candleView.rows.length?<svg className="kline-chart" viewBox="0 0 900 300" role="img" aria-label={`${asset} ${candleInterval} K线图（${currencyShort(candleCurrency)}）`}><g className="kline-grid">{[0,1,2,3,4].map(i=><line key={`h-${i}`} x1="26" x2="874" y1={20+i*59.5} y2={20+i*59.5}/>)}{[0,1,2,3,4].map(i=><line key={`v-${i}`} x1={26+i*212} x2={26+i*212} y1="20" y2="258"/>)}</g><text className="kline-axis-label" x="30" y="14">{candleView.max.toLocaleString('en-US',{maximumFractionDigits:3})} {currencyShort(candleCurrency)}</text><text className="kline-axis-label" x="30" y="274">{candleView.min.toLocaleString('en-US',{maximumFractionDigits:3})} {currencyShort(candleCurrency)}</text>{candleView.rows.map((c,i)=><g key={`${c.time}-${i}`} className={c.up?'candle up':'candle down'}><line x1={c.x} x2={c.x} y1={c.wickTop} y2={c.wickBottom}/><rect x={c.x-c.w/2} y={c.bodyTop} width={c.w} height={c.bodyHeight} rx="1"/><title>{`${formatBeijingDateTime(c.time)} 开 ${c.open.toFixed(3)} 高 ${c.high.toFixed(3)} 低 ${c.low.toFixed(3)} 收 ${c.close.toFixed(3)} ${currencyShort(candleCurrency)}`}</title></g>)}</svg>:<div className="kline-empty">暂无可显示的 K 线数据</div>}</div><div className="kline-foot"><span><i className={candles?.is_live?'live-dot':''}/>{candles?.note||'数据加载后显示来源、时间与数据模式。'}</span><span>{candles?.source_url?<a href={candles.source_url} target="_blank" rel="noreferrer">查看来源 ↗</a>:''} {candleError||`自动刷新 ${refreshText} · ${currencyShort(candleCurrency)}`}</span></div></section>
   {showQuality&&<section className="quality-panel" aria-label="100点优化审计"><div className="quality-intro"><div><b>100 点优化审计 · 10 家平台 × 10 项能力</b><p>这是可追踪的产品与研究流程清单，不是收益率或胜率保证；每项状态明确区分已落地、接入后完善和需授权。</p></div><span className="quality-version">迭代 01 · 可回滚</span></div><div className="quality-summary"><div><strong>100</strong><span>检查点</span></div><div className="done"><strong>{optimizationCounts['已落地']}</strong><span>已落地</span></div><div className="pending"><strong>{optimizationCounts['接入后完善']}</strong><span>接入后完善</span></div><div className="locked"><strong>{optimizationCounts['需授权']}</strong><span>需授权</span></div></div><div className="quality-controls"><span>筛选状态</span>{optimizationStates.map(state=><button key={state} className={optimizationFilter===state?'selected':''} onClick={()=>setOptimizationFilter(state)}>{state}{state==='全部'?` · ${optimizationChecks.length}`:` · ${optimizationCounts[state]}`}</button>)}</div><div className="quality-platforms">{benchmarkPlatforms.map(platform=><span key={platform.name}><b>{platform.name}</b><small>{optimizationPlatformCounts[platform.name]||0} 点 · {optimizationBlueprint.find(group=>group.platform===platform.name)?.basis}</small></span>)}</div><div className="quality-grid">{visibleOptimizationChecks.map(q=><span key={q.id} className={`quality-check quality-${q.state==='已落地'?'done':q.state==='接入后完善'?'pending':'locked'}`} title={`${q.platform} · ${q.category} · ${q.basis}`}><i>{q.state==='已落地'?'✓':q.state==='接入后完善'?'↻':'▣'}</i><small>{String(q.id).padStart(3,'0')}</small><b>{q.label}</b><em>{q.platform}</em></span>)}</div><div className="benchmark-links"><a href="https://www.tradingview.com/features/" target="_blank" rel="noreferrer">TradingView 能力参考 ↗</a><a href="https://professional.bloomberg.com/products/bloomberg-terminal/" target="_blank" rel="noreferrer">Bloomberg Terminal ↗</a><a href="https://www.lseg.com/en/data-analytics/products/workspace" target="_blank" rel="noreferrer">LSEG Workspace ↗</a><a href="https://www.factset.com/solutions/workstation" target="_blank" rel="noreferrer">FactSet Workstation ↗</a></div></section>}
    <div className="content-grid"><section id="intel" className="panel intel"><div className="panel-head"><div><h2>今日情报雷达</h2><p>已去重并按发布时间排序 · 每条资讯保留原始来源 · 全球事件 {eventSyncStatus}{eventSyncedAt?` · ${formatSyncTime(eventSyncedAt)}`:''}{eventSyncLatency===null?'':` · ${eventSyncLatency} ms`}</p>{eventSyncError&&<small className="event-sync-error">{eventSyncError}</small>}</div><div className="legend"><div className="filter-tabs">{(['全部','已验证','变化'] as const).map(x=><button key={x} className={filter===x?'selected':''} onClick={()=>setFilter(x)}>{x}</button>)}</div><span><i className="bull"/>利多</span><span><i className="bear-dot"/>利空</span><span><i className="neutral-dot"/>中性</span></div></div><div className="side-columns">{(['利多','利空','中性'] as const).map(side=><div key={side}><h3 className={side==='利多'?'bull-text':side==='利空'?'bear':'neutral-text'}>{side==='利多'?'▲ 利多驱动':side==='利空'?'▼ 利空压力':'• 中性待验证'} <span>{filtered.filter(e=>e.side===side).length}</span></h3>{filtered.filter(e=>e.side===side).map(e=><article className="event" key={e.id} onClick={()=>setSelected(e)} tabIndex={0} onKeyDown={ev=>ev.key==='Enter'&&setSelected(e)}><div className="event-meta"><span>{e.time} 北京时间</span><b>{e.source}</b><em>影响 {e.impact}</em></div><h4>{e.title}</h4><p>{e.summary}</p><div className="tags">{e.tags.map(t=><span key={t}>{t}</span>)}</div><footer><span>置信度 <b>{e.confidence}%</b></span><a href={e.sourceUrl} target="_blank" rel="noreferrer" onClick={ev=>ev.stopPropagation()}>查看来源 ↗</a><span className="detail-hint">详情 ›</span></footer></article>)}</div>)}</div></section>
    <aside className="right-stack"><section className="panel pulse"><div className="panel-head"><div><h2>市场脉搏</h2><p>近 12 小时观点变化</p></div><span className="trend">+12%</span></div><div className="chart"><div className="gridlines"/><div className="area-shape"/><div className="line-shape"/><span className="marker m1">宏观</span><span className="marker m2">库存</span></div><div className="chart-axis"><span>22:00</span><span>02:00</span><span>06:00</span><span>10:00</span></div></section><section id="changes" className="panel changes"><div className="panel-head"><div><h2>最新变化</h2><p>相较上次刷新 · 可审计</p></div><button onClick={()=>setToast('变化日志已标记为已读')}>标记已读</button></div><ul><li><i className="new">新</i><div><b>新增宏观事件</b><p>{asset}数据窗口进入观察</p><small>2 分钟前 · <span className="green-text">added</span></small></div></li><li><i className="up">↗</i><div><b>观点由中性转为{assets[asset].tone}</b><p>价格与基本面信号待交叉验证</p><small>18 分钟前 · <span className="green-text">sentiment_changed</span></small></div></li><li><i className="adjust">调</i><div><b>策略区间调整</b><p>{currentPlan.invalid}</p><small>36 分钟前 · <span className="amber-text">strategy_adjusted</span></small></div></li></ul></section><section id="risk" className="panel risk-card"><div className="panel-head"><div><h2>风险与催化剂</h2><p>下一个需要盯住的变量</p></div><span className="risk-state">中等</span></div><div className="risk-list"><p><i className="catalyst"/><span><b>催化剂</b>　{assetContext[asset].catalyst}</span><strong>+↑</strong></p><p><i className="risk"/><span><b>风险</b>　{assetContext[asset].risk}</span><strong>−↓</strong></p><p><i className="neutral-dot"/><span><b>验证</b>　{assetContext[asset].verify}</span><strong>待定</strong></p></div></section></aside></div>
   <section id="strategy" className="panel week"><div className="panel-head"><div><h2>未来 7 日策略路径</h2><p>基于当前市场状态动态更新 · 仅供研究参考</p></div><div className="risk-badge">风险预算 <b>中等</b></div></div><div className="week-grid">{days.map((d,i)=><article key={d} className={i===0?'today':''}><span>{d}</span><b>{i===0?'今日':`9/${4+i}`}</b><i className={i<2?'bull':i<5?'neutral':'quiet'}/><p>{strategy[asset][i]}</p><small>{i===2?'⚡ 重要数据':'仓位 ≤ '+(i<4?'40%':'25%')}</small></article>)}</div></section><footer className="disclaimer"><span>数据来源：GDELT、Alpha Vantage、FRED、CFTC 等公开渠道 · Provider 状态以页面标注为准</span><b>风险提示：本平台内容不构成投资建议</b></footer>
  <div className="data-state-float"><i className={snapshot?'online':''}/><span>{dataStatus}</span><b>{active.price}</b><small className="currency-tag">{currencyShort(activeCurrency)}</small></div>{toast&&<div className="toast">✓ {toast}</div>}{selected&&<div className="modal-backdrop" onClick={()=>setSelected(null)}><section className="detail-modal" onClick={e=>e.stopPropagation()}><button className="close" onClick={()=>setSelected(null)} aria-label="关闭">×</button><span className={selected.side==='利多'?'modal-side bull-text':selected.side==='利空'?'modal-side bear':'modal-side neutral-text'}>{selected.side} · 影响 {selected.impact}/100</span><h2>{selected.title}</h2><p className="modal-summary">{selected.summary}</p><div className="explain"><div><span>来源可信度</span><b>高 · {selected.source}</b></div><div><span>跨源验证</span><b>{selected.confidence >= 80 ? '2 / 3 来源一致' : '待更多来源'}</b></div><div><span>时效评分</span><b>{selected.time} 发布 · 仍在窗口内</b></div><div><span>研判动作</span><b>{selected.side==='利多'?'回踩关注做多机会':selected.side==='利空'?'反弹减仓并收紧止损':'等待价格与基本面信号确认'}</b></div></div><a className="source-link" href={selected.sourceUrl} target="_blank" rel="noreferrer">打开原始资讯来源 ↗</a></section></div>}
 <section id="platforms" className="platform-compare panel"><div className="sources-intro"><div><h2>全球 10 家主流分析平台对标</h2><p>借鉴图表、事件、宏观、订单流、组合与执行能力；官方能力页面可直接访问</p></div><span>{benchmarkPlatforms.length} 家平台</span></div><div className="platform-grid">{benchmarkPlatforms.map((p,i)=><article key={p.name}><div className="platform-top"><span className={`platform-rank rank-${i+1}`}>{String(i+1).padStart(2,'0')}</span><div><h3>{p.name}</h3><small>{p.tag}</small></div></div><p><b>优势：</b>{p.strength}</p><p><b>取舍：</b>{p.tradeoff}</p><footer><span>适合：{p.fit}</span><a href={p.url} target="_blank" rel="noreferrer">官方网址 ↗</a></footer></article>)}</div></section>
 <section className="event-index"><div className="sources-intro"><div><h2>资讯时间索引</h2><p>按发布时间从新到旧 · 时间为北京时间 · 点击可访问原始来源</p></div><span>{filtered.length} 条</span></div><div className="event-index-list">{filtered.map(e=><div key={`index-${e.id}`}><time dateTime={e.publishedAt}>{formatBeijingDateTime(e.publishedAt)} 北京时间</time><span className={e.side==='利多'?'bull-text':e.side==='利空'?'bear':'neutral-text'}>{e.side}</span><b>{e.title}</b><a href={e.sourceUrl} target="_blank" rel="noreferrer">{e.source} 原文 ↗</a></div>)}</div></section>
 <section className="week-impact panel"><div className="panel-head"><div><h2>过去 / 未来 7 日关键影响事件</h2><p>时间轴按日期排序；过去事件由全球事件源轮询更新，未来日期为计划窗口 · {eventSyncStatus}{eventSyncedAt?` · 最近 ${formatSyncTime(eventSyncedAt)}`:''}</p></div><div className="timeline-filter">{(['全部','过去7天','未来7天'] as const).map(x=><button key={x} className={eventWindow===x?'selected':''} onClick={()=>setEventWindow(x)}>{x}</button>)}</div></div><div className="timeline-list">{timelineEvents.map(e=><article className="timeline-item" key={e.id}><div className={`timeline-dot ${e.side==='利多'?'bull-side':e.side==='利空'?'bear-side':'neutral-side'}`}/><time dateTime={e.date}>{e.date.slice(5).replace('-','/')} · {e.window} · 北京时间</time><span className={e.side==='利多'?'bull-text':e.side==='利空'?'bear':'neutral-text'}>{e.side} · {e.impact}影响</span><div><h3>{e.title}</h3><p>{e.why}</p><small>影响品种：{e.assets}</small></div><a href={e.sourceUrl} target="_blank" rel="noreferrer">{e.source} 原文 ↗</a></article>)}</div></section>
 <section className="trade-now panel"><div className="panel-head"><div><h2>今日当下交易策略 · {asset}</h2><p>由多空强度、可用行情状态和事件窗口共同生成；仅供研究参考</p></div><span className={`mode-badge ${activeSnapshot?'has-data':''}`}>{activeSnapshot?snapshotLabel(activeSnapshot):'演示数据'}</span></div><div className="trade-grid"><div className="now-signal"><span>当前倾向</span><strong>{currentPlan.bias}</strong><b>{active.price} <small className="currency-tag">{currencyShort(activeCurrency)}</small>　{active.change}</b><small>多空强度 {assets[asset].score}/100 · {activeSnapshot?.provider||'demo'} · {activeSnapshot?.as_of?formatBeijingDateTime(activeSnapshot.as_of):'等待刷新'}</small></div><div><span>执行计划</span><p>{currentPlan.action}</p><small>触发：{currentPlan.trigger} · {currencyShort(activeCurrency)}</small></div><div><span>风控边界</span><p>{currentPlan.invalid}</p><small>仓位：{currentPlan.size}</small></div><div><span>下一催化剂</span><p>{currentPlan.next}</p><small>事件前后不追价，等待价格与数据共振</small></div></div><div className="data-note"><i/>行情状态：{dataStatus} · 价格单位：{currencyLabel(activeCurrency)}。公开免费通道仅在其明确支持的品种上提供现货/外汇实时或日频参考；锡等交易所期货仍需授权行情，平台不会将演示值标为实盘。</div></section>
 <section className="data-coverage panel"><div className="sources-intro"><div><h2>全球期货数据覆盖</h2><p>优先展示可获取、可追溯且标注时效的数据；点击来源可核验</p></div><span>Provider 可替换</span></div><div className="coverage-grid"><a href="https://www.alphavantage.co/documentation/" target="_blank" rel="noreferrer"><b>黄金 / 白银</b><span>Alpha Vantage GOLD_SILVER_SPOT</span><em>免费 Key：国际现货实时</em></a><a href="https://www.alphavantage.co/documentation/" target="_blank" rel="noreferrer"><b>铜 / 原油</b><span>Alpha Vantage COPPER / WTI</span><em>免费 Key：日频参考</em></a><a href="https://www.alphavantage.co/documentation/" target="_blank" rel="noreferrer"><b>美元</b><span>Alpha Vantage USD/CNY 外汇</span><em>免费 Key：外汇实时</em></a><a href="https://www.shfe.com.cn/reports/marketdata/delayedquotes/" target="_blank" rel="noreferrer"><b>沪金 / 沪银 / 沪铜 / 沪锡 / 原油</b><span>SHFE 官网公开 JSON</span><em>公开版：官方延时 · 60s 轮询</em></a><a href="https://www.shfe.com.cn/data/tradedata/future/delaymarket/delaymarket_all.dat" target="_blank" rel="noreferrer"><b>上期所延时 JSON</b><span>delaymarket_all.dat</span><em>无 Key · 官方公开文件</em></a><a href="https://www.lme.com/Metals/Non-ferrous/LME-Tin" target="_blank" rel="noreferrer"><b>锡</b><span>LME 官方库存与结算</span><em>需授权：非实时</em></a><a href="https://publicreporting.cftc.gov/stories/s/r4w3-av2u" target="_blank" rel="noreferrer"><b>CFTC COT</b><span>持仓周报，识别拥挤度</span><em>周频 · 免费</em></a><a href="https://fred.stlouisfed.org/docs/api/fred/" target="_blank" rel="noreferrer"><b>FRED 宏观</b><span>实际利率 / 美元 / 原油</span><em>日频 · 免费 Key</em></a><a href="#private-data"><b>本人 CTP Bridge</b><span>私有登录后实时行情</span><em>不公开 · 需本人 Bridge</em></a></div></section>
 <section className="sources-panel"><div className="sources-intro"><div><h2>数据质量与来源状态</h2><p>延迟、完整性、登录范围和许可状态按公开/私有通道分别标注</p></div><span>6 个数据适配器</span></div><div className="source-grid">{sourceHealth.map(s=><div key={s[0]}><i/><b>{s[0]}</b><small>{s[1]}</small><strong>{s[0]==='SHFE 官方延时'?(domesticSync?.status==='ok'?'在线':domesticSync?.status==='provider_error'?'异常':'同步中'):s[2]}</strong></div>)}</div></section>
 <footer id="official" className="official-links"><div className="sources-intro"><div><h2>常用期货官方入口</h2><p>交易所、监管与持仓资料原站链接；行情许可请以各机构条款为准</p></div><span>官方来源</span></div><div className="official-grid">{officialFuturesLinks.map(([name,desc,url])=><a key={name} href={url} target="_blank" rel="noreferrer"><b>{name}</b><span>{desc}</span><em>访问官网 ↗</em></a>)}</div><small className="official-note">期鉴只聚合与解释公开信息，不代表任何交易所、数据商或经纪商；链接打开后请以官方页面为准。</small></footer>
 </main></div>
